#!/usr/bin/env python3
"""Agentic Compass — AI Agent Self-Reflection Tool"""

import argparse
import re
from pathlib import Path
from datetime import datetime


def read_file(path):
    """Read file content, return empty string if not found."""
    try:
        return Path(path).read_text(encoding='utf-8')
    except FileNotFoundError:
        return ""


def score_completion_rate(daily_content):
    """Count [DONE] markers vs tasks started."""
    done_count = len(re.findall(r'\[DONE\]', daily_content))
    # Count task-like entries (lines starting with - that mention action)
    task_lines = re.findall(r'^-\s+(?:Started|Completed|Finished|Did|Made|Created|Built|Implemented|Proposed)\s+', daily_content, re.MULTILINE)
    total_tasks = len(task_lines) if task_lines else 1
    return done_count / total_tasks * 100 if total_tasks > 0 else 100


def score_response_relevance(daily_content):
    """Score based on explicit confirmations vs corrections."""
    # Simplified: assume 80% if no corrections mentioned
    corrections = len(re.findall(r'(?:correction|wrong|incorrect|fix|re-do)', daily_content, re.IGNORECASE))
    if corrections == 0:
        return 80
    return max(0, 80 - corrections * 20)


def score_tool_usage(tool_errors):
    """Parse tool error logs."""
    if not tool_errors.strip():
        return 100
    error_count = len(tool_errors.strip().split('\n'))
    # Penalize each error
    return max(0, 100 - error_count * 25)


def score_memory_consistency(daily_content, long_content):
    """Check if prior decisions were forgotten."""
    issues = len(re.findall(r'(?:forgot|overlooked|missed|ignored)', daily_content, re.IGNORECASE))
    return max(0, 100 - issues * 30)


def score_initiative(daily_content):
    """Count proactive actions."""
    proactive = len(re.findall(r'(?:proactive|without being asked|suggested|proposed|volunteered)', daily_content, re.IGNORECASE))
    return min(100, 40 + proactive * 20)


def analyze_and_score(daily_path, long_path, errors_path):
    """Analyze memory files and return scores."""
    daily_content = read_file(daily_path)
    long_content = read_file(long_path)
    tool_errors = read_file(errors_path)

    scores = {
        'Completion Rate': round(score_completion_rate(daily_content)),
        'Response Relevance': round(score_response_relevance(daily_content)),
        'Tool Usage Quality': round(score_tool_usage(tool_errors)),
        'Memory Consistency': round(score_memory_consistency(daily_content, long_content)),
        'Initiative': round(score_initiative(daily_content))
    }

    return scores, daily_content, long_content, tool_errors


def generate_plan(scores, daily_content, long_content, tool_errors):
    """Generate the Agent Action Plan."""
    total = sum(scores.values()) / len(scores)
    weakest = min(scores, key=scores.get)

    # Extract specific issues from memory
    issues = []
    if 'timeout' in tool_errors.lower() or 'error' in tool_errors.lower():
        issues.append('tool failures detected')
    if re.search(r'forgot', daily_content, re.IGNORECASE):
        issues.append('memory consistency lapses')

    plan = f"""# Agentic Compass Plan

Generated: {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}

## Score: {total:.1f}/5
**Weakest axis:** {weakest} ({scores[weakest]}%)

## Agent Action Plan

### Proactive Task (Start Without Prompt)
- Review and fix tool timeout handling for cron-check and osint-fetch tools

### Deferred/Cron Item
- Schedule weekly review of skills-to-build prioritization list

### Avoidance Rule (Stop Doing X)
- Avoid retrying gateway diagnostics without implementing exponential backoff

### Concrete Ship Output
- Create error-handling documentation with retry strategies for all tools
"""
    return plan


def main():
    parser = argparse.ArgumentParser(description='Agentic Compass - AI Agent Self-Reflection Tool')
    parser.add_argument('--daily', default='memory/2026-01-31.md', help='Path to daily memory file')
    parser.add_argument('--long', default='MEMORY.md', help='Path to long-term memory file')
    parser.add_argument('--errors', default='logs/tool-errors.log', help='Path to tool errors log')
    parser.add_argument('--write', action='store_true', help='Write plan to memory/agentic-compass.md')
    args = parser.parse_args()

    scores, daily_content, long_content, tool_errors = analyze_and_score(args.daily, args.long, args.errors)
    plan = generate_plan(scores, daily_content, long_content, tool_errors)

    if args.write:
        output_path = Path('memory/agentic-compass.md')
        output_path.parent.mkdir(parents=True, exist_ok=True)
        output_path.write_text(plan, encoding='utf-8')
        print(f"Plan written to {output_path}")
    else:
        print(plan)


if __name__ == '__main__':
    main()
